diff --git a/src/knownhost.c b/src/knownhost.c
index 2bd41de..1ae3232 100644
--- a/src/knownhost.c
+++ b/src/knownhost.c
@@ -419,6 +419,13 @@ static int knownhost_parse_ipv4(const char *src, const char *end,
     return 1;
 }

+/* True if 'width' more 16-bit words still fit in the 8-word IPv6 buffer
+   after 'count' of them are already in use. */
+static int knownhost_ipv6_word_fits(size_t count, size_t width)
+{
+    return count + width <= 8;
+}
+
 static int knownhost_parse_ipv6(const char *src, size_t len,
                                 unsigned char result[16])
 {
@@ -458,7 +465,8 @@ static int knownhost_parse_ipv6(const char *src, size_t len,
         if(p < end && *p == '.') {
             unsigned char ipv4[4];

-            if(count > 6 || !knownhost_parse_ipv4(part, end, ipv4))
+            if(!knownhost_ipv6_word_fits(count, 2) ||
+               !knownhost_parse_ipv4(part, end, ipv4))
                 return 0;

             words[count++] =
@@ -468,7 +476,7 @@ static int knownhost_parse_ipv6(const char *src, size_t len,
             break;
         }

-        if(!digits || count >= 8)
+        if(!digits || !knownhost_ipv6_word_fits(count, 1))
             return 0;

         words[count++] = (unsigned short)value;

